css:
& .am-head { margin-bottom: 22px; }
& .am-head h1 { font-family: var(--font-reading); font-size: calc(36px * var(--am-scale, 1)); line-height: 1.25; font-weight: 500; letter-spacing: -0.035em; color: var(--title-1); }
& .am-head-meta { border-top: 1px solid var(--line); padding-top: 12px; margin-top: 16px; }
& .am-intro { font-size: calc(15px * var(--am-scale, 1)); line-height: 1.8; color: var(--ink-2); }
& .am-panel { border-color: var(--line); scroll-margin-top: 80px; }
& .am-panel-head { min-height: 42px; border-bottom: 1px solid var(--line-2); }
& .am-panel-head h2 { font-family: var(--font-reading); font-size: calc(18px * var(--am-scale, 1)); font-weight: 500; line-height: 1.4; letter-spacing: -0.015em; color: var(--title-2); padding-block: 8px; }
& .am-panel-id { align-self: center; min-width: 25px; height: 25px; margin-inline-start: 14px; border: 1px solid var(--line); border-radius: 6px; font: calc(11px * var(--am-scale, 1))/1 var(--font-mono); }
& .am-panel-body { padding: 14px 16px 16px; }
& .am-md { line-height: 1.8; }
& .am-md p { margin-bottom: 10px; }
& .am-md h1, & .am-md h2, & .am-md h3, & .am-md h4, & .am-md h5, & .am-md h6 { font-family: var(--font-reading); font-weight: 600; line-height: 1.4; margin-block: 20px 8px; }
& .am-md strong, & .am-intro strong { font-weight: 650; color: var(--ink); }
& .am-md a { text-decoration-thickness: 1px; text-underline-offset: 4px; }
& .am-md blockquote { padding: 8px 14px; border-inline-start: 2px solid var(--accent); background: var(--accent-bg); border-radius: 0 6px 6px 0; }
& .am-md > ul, & .am-md > ol { padding-block: 10px; padding-inline: 30px 14px; border: 1px solid var(--line-2); border-radius: 8px; background: var(--paper); }
& .am-md > ul > li, & .am-md > ol > li { padding-inline-start: 3px; }
& .am-md th { font-family: var(--font-sans); font-weight: 600; color: var(--ink-2); padding-block: 10px; }
& .am-md td { padding-block: 10px; }
& .am-md figure { margin: 0; border: 1px solid var(--line); border-radius: 8px; background: var(--fill); overflow: hidden; }
& .am-md figure::before { content: ""; display: block; height: 28px; border-bottom: 1px solid var(--line-2); background: radial-gradient(circle at 14px 14px, var(--signal-red) 3px, transparent 3.5px), radial-gradient(circle at 27px 14px, var(--signal-yellow) 3px, transparent 3.5px), radial-gradient(circle at 40px 14px, var(--signal-green) 3px, transparent 3.5px); }
& .am-md figure img { display: block; margin: 0 auto; border: 0; border-radius: 0; }
& .am-md figure figcaption { margin: 0; padding: 10px 14px; color: var(--ink-2); border-top: 1px solid var(--line-2); font-size: calc(12px * var(--am-scale, 1)); text-align: start; }
& .am-kv { border-color: var(--line); border-radius: 8px; overflow: hidden; }
& .am-callout { border-radius: 8px; }
& .am-callout-title { font-weight: 600; }
& .am-comment-btn { color: var(--ink-2); }
& .am-comment-btn--on { color: var(--accent); }
@media (max-width: 760px) { & .am-head { margin-top: 60px; } & .am-head h1 { font-size: calc(28px * var(--am-scale, 1)); } & .am-panel-body { padding: 14px 16px 16px; } & .am-panel-head h2 { font-size: calc(18px * var(--am-scale, 1)); } & .am-panel { scroll-margin-top: 110px; } }
@media print { & .am-panel { box-shadow: none; } & .am-md figure::before { print-color-adjust: exact; } }
& .am-md h1 { font-size: calc(28px * var(--am-scale, 1)); color: var(--title-1); }
& .am-md h2 { font-size: calc(24px * var(--am-scale, 1)); color: var(--title-2); }
& .am-md h3 { font-size: calc(20px * var(--am-scale, 1)); color: var(--title-3); }
& .am-md h4 { font-size: calc(17px * var(--am-scale, 1)); color: var(--title-4); }
& .am-md h5 { font-size: calc(15px * var(--am-scale, 1)); color: var(--title-5); }
& .am-md h6 { font-size: calc(13px * var(--am-scale, 1)); color: var(--title-6); }
& .am-md > ul > li:nth-child(3n+1)::marker, & .am-md > ol > li:nth-child(3n+1)::marker { color: var(--signal-red); }
& .am-md > ul > li:nth-child(3n+2)::marker, & .am-md > ol > li:nth-child(3n+2)::marker { color: var(--signal-yellow); }
& .am-md > ul > li:nth-child(3n)::marker, & .am-md > ol > li:nth-child(3n)::marker { color: var(--signal-green); }
& .am-md > div:has(> table), & .am-panel-body > figure:has(> pre) { border: 1px solid var(--line); border-radius: 8px; background: var(--paper); overflow-x: auto; margin-block: 12px; }
& .am-md > div:has(> table)::before { content: ""; display: block; height: 28px; border-bottom: 1px solid var(--line-2); background-color: var(--fill); background-image: radial-gradient(circle at 14px 14px, var(--signal-red) 3px, transparent 3.5px), radial-gradient(circle at 27px 14px, var(--signal-yellow) 3px, transparent 3.5px), radial-gradient(circle at 40px 14px, var(--signal-green) 3px, transparent 3.5px); }
& .am-md table { margin: 0; }
& .am-md tbody tr:last-child td { border-bottom: 0; }
& .am-panel .am-panel-body > figure:has(> pre) > figcaption { border: 0; border-bottom: 1px solid var(--line-2); border-radius: 0; background: var(--paper); }
& .am-panel .am-panel-body > figure:has(> pre) > pre { margin: 0; border: 0; border-radius: 0; }
& .am-md, & .am-intro { font-size: calc(16px * var(--am-scale, 1)); line-height: 1.8; }
& .am-head h1, & .am-panel-head h2 { letter-spacing: 0; font-weight: 600; }
& .am-callout { background: var(--warn-bg); border-inline-start-color: var(--warn); }
& .am-callout--ok { background: var(--ok-bg); border-inline-start-color: var(--ok); }
& .am-callout--err { background: var(--err-bg); border-inline-start-color: var(--err); }
& body { font-family: var(--font-reading); }
& .am-panel .am-panel-body > figure:has(> pre) > figcaption { display: flex; align-items: center; flex-wrap: nowrap; gap: 10px; min-height: 44px; padding: 9px 12px; background: var(--fill); }
& .am-panel .am-panel-body > figure:has(> pre) > figcaption::before { content: ""; display: block; flex: 0 0 34px; width: 34px; height: 8px; background-image: radial-gradient(circle at 4px 4px, var(--signal-red) 3px, transparent 3.5px), radial-gradient(circle at 17px 4px, var(--signal-yellow) 3px, transparent 3.5px), radial-gradient(circle at 30px 4px, var(--signal-green) 3px, transparent 3.5px); }
& .am-panel .am-panel-body > figure:has(> pre) > figcaption > span:first-child { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
& .am-panel .am-panel-body > figure:has(> pre > code[data-lang]) > figcaption > span:last-of-type { flex: 0 0 auto; margin-inline-start: auto; padding: 3px 8px; border: 1px solid var(--chip-border); border-radius: 6px; background: linear-gradient(180deg, var(--chip-top), var(--chip-bottom)); color: var(--title-3); box-shadow: 0 2px 0 var(--chip-depth), inset 0 1px 0 var(--chip-highlight); font: 600 calc(11px * var(--am-scale, 1))/1.4 var(--font-mono); white-space: nowrap; }
@media print { & .am-panel .am-panel-body > figure:has(> pre > code[data-lang]) > figcaption > span:last-of-type { box-shadow: none; } }
& .am-md table { font-family: var(--font-sans); }
& .am-md > p, & .am-md > blockquote, & .am-md > ul, & .am-md > ol { max-width: var(--reading-measure); }
& main:has(> .am-head) { max-width: 1288px; }
& main > div:has(> nav) > div:has(> .am-panel) { display: flex; flex-wrap: wrap; align-items: flex-start; gap: 20px; }
& main > div:has(> nav) > div:has(> .am-panel) > .am-panel { flex: 1 1 100%; min-width: 0; margin-block-start: 0; }
& main > div:has(> nav) > div:has(> .am-panel) > .am-panel:has([data-card="half"]) { flex-basis: 30rem; min-width: min(100%, 30rem); }
& main > div:has(> nav) > div:has(> .am-panel) > .am-panel:has([data-card="third"]) { flex-basis: 21rem; min-width: min(100%, 21rem); }
& .am-panel:has([data-card="important"]) { border-color: color-mix(in srgb, var(--signal-yellow) 30%, var(--line)); }
& .am-panel:has([data-card="important"]) > .am-panel-head { background: var(--fill); border-bottom-color: var(--line); }
& .am-panel:has([data-card="important"]) > .am-panel-head::before { content: ""; display: block; align-self: center; flex: 0 0 34px; width: 34px; height: 8px; margin-inline: 14px 0; background: radial-gradient(circle at 4px 4px, var(--signal-red) 3px, transparent 3.5px), radial-gradient(circle at 17px 4px, var(--signal-yellow) 3px, transparent 3.5px), radial-gradient(circle at 30px 4px, var(--signal-green) 3px, transparent 3.5px); }
& .am-panel:has([data-card="important"]) > .am-panel-head > .am-panel-id { margin-inline-start: 8px; }
& { color-scheme: var(--theme-color-scheme); }
